export interface SwitchProps {
    /** Switch value */
    modelValue?: boolean | number | string;
    /** Whether Switch is disabled */
    disabled?: boolean;
    /** Switch width */
    width?: number | string;
    /** Active color */
    activeColor?: string;
    /** Inactive color */
    inactiveColor?: string;
    /** Active value */
    activeValue?: boolean | number | string;
    /** Inactive value */
    inactiveValue?: boolean | number | string;
}
